package fieldinfo

//go:generate optgen generate

// DefaultMaxDepth is the default value for [WithMaxDepth]: the nested
// messages a walk descends before it fails with [ErrMaxDepthExceeded]. It
// matches the fieldbehavior default.
const DefaultMaxDepth = 32

// options configures a [Checker]. Tunables are generated by optgen — use
// [WithMaxDepth], [WithJSONNames] and [WithRegistry].
type options struct {
	// WithMaxDepth bounds the nested messages a walk descends. Zero is
	// unlimited; a negative value keeps the default.
	maxDepth int `optgen:"default=DefaultMaxDepth" optval:"positive=allow_zero"`
	// WithJSONNames spells the field segments of violation paths with their
	// JSON (lowerCamelCase) names, "dnsServers.1", instead of their proto
	// names, "dns_servers.1" (the default, matching fieldbehavior and
	// fieldmask paths).
	jsonNames bool `optval:"param"`
	// WithRegistry supplies the custom formats and the fields they apply to.
	// The registry is copied when the checker is built. Nil means none.
	registry *Registry `optgen:"allownull"`
}
